public class ContactTriggerHandler {

    public static void execute() {
        if (Trigger.isBefore) {
            handleBefore();
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert();
        }
    }

    // ── Before insert / before update ──────────────────────────────────────
    // 1 SOQL query: fetch BillingCountry & AccountSource for all referenced
    //               accounts in a single statement.
    // 0 DML statements (before context – we mutate sObject fields directly).
    private static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource
             FROM Account
             WHERE Id IN :accountIds]
        );

        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                Account a = accountMap.get(c.AccountId);
                if (a == null) {
                    continue;
                }
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    // ── After insert ───────────────────────────────────────────────────────
    // 1 SOQL query: fetch Phone for all referenced accounts (only those whose
    //               contacts carry a non-blank phone).
    // 1 DML statement: a single bulk update of all accounts that need a phone.
    //
    // Behaviour preserved: when several new contacts share the same account
    // and the account has no phone, the *first* contact in Trigger.new order
    // supplies the phone.  Subsequent contacts for that account are ignored.
    private static void handleAfterInsert() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone
             FROM Account
             WHERE Id IN :accountIds]
        );

        // Track accounts we have already "processed" so that only the first
        // qualifying contact (in trigger order) can set the phone.
        Set<Id> processedAccounts = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            if (processedAccounts.contains(c.AccountId)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            processedAccounts.add(c.AccountId);
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
