public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private class RateResponse {
        public String base;
        public String date;
        public Map<String, Decimal> rates;
    }

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validation (no callout) ---
        String base = normalise(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String code : quoteCurrencies) {
            normalisedQuotes.add(normalise(code));
        }

        // --- Build request ---
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:FB_Exchange_Rates/v1/latest?base=' + base + '&symbols=' + String.join(normalisedQuotes, ','));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        req.setTimeout(60000);

        // --- Execute (with single retry on 503) ---
        HttpResponse res;
        try {
            res = new Http().send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Callout failed: ' + e.getMessage());
        }

        Integer status = res.getStatusCode();

        if (status == 503) {
            try {
                res = new Http().send(req);
            } catch (CalloutException e) {
                throw new ExchangeRateException('Callout failed on retry: ' + e.getMessage());
            }
            status = res.getStatusCode();
        }

        if (status != 200) {
            throw new ExchangeRateException('Unexpected HTTP status code: ' + status);
        }

        // --- Parse response ---
        RateResponse parsed;
        try {
            parsed = (RateResponse) JSON.deserialize(res.getBody(), RateResponse.class);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body: ' + e.getMessage());
        }

        if (parsed == null || parsed.rates == null) {
            throw new ExchangeRateException('Response body is missing the rates object.');
        }

        // --- Build result (only requested codes) ---
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalisedQuotes) {
            if (!parsed.rates.containsKey(code) || parsed.rates.get(code) == null) {
                throw new ExchangeRateException('No rate returned for currency: ' + code);
            }
            result.put(code, parsed.rates.get(code));
        }

        return result;
    }

    private static String normalise(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (normalised.length() != 3 || !Pattern.matches('^[A-Z]{3}$', normalised)) {
            throw new ExchangeRateException('Invalid currency code: must be exactly three letters A-Z.');
        }
        return normalised;
    }
}
