public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {
    }

    public static Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('Body is null or blank');
            }

            Object parsed = JSON.deserialize(body);

            if (!(parsed instanceof Map)) {
                throw new PayloadException('JSON is not an object');
            }

            Map<String, Object> payload = (Map<String, Object>) parsed;

            // --- number (required, must be a non-blank string) ---
            if (!payload.containsKey('number') || payload.get('number') == null) {
                throw new PayloadException('Missing number');
            }
            Object numberObj = payload.get('number');
            if (!(numberObj instanceof String)) {
                throw new PayloadException('Number is not a string');
            }
            String number = (String) numberObj;
            if (String.isBlank(number)) {
                throw new PayloadException('Number is blank');
            }

            // --- Build Order ---
            Order order = new Order();
            order.orderNumber = number;

            // date
            if (payload.containsKey('date') && payload.get('date') != null) {
                Object dateObj = payload.get('date');
                if (dateObj instanceof String) {
                    order.orderDate = Date.valueOf((String) dateObj);
                }
            }

            // currency
            if (payload.containsKey('currency') && payload.get('currency') != null) {
                Object currObj = payload.get('currency');
                if (currObj instanceof String) {
                    order.currencyCode = (String) currObj;
                }
            }

            // customer
            order.customerEmail = null;
            if (payload.containsKey('customer') && payload.get('customer') != null) {
                Object custObj = payload.get('customer');
                if (custObj instanceof Map) {
                    Map<String, Object> customer = (Map<String, Object>) custObj;
                    if (customer.containsKey('email') && customer.get('email') != null) {
                        Object emailObj = customer.get('email');
                        if (emailObj instanceof String) {
                            order.customerEmail = (String) emailObj;
                        }
                    }
                }
            }

            // lines
            order.lines = new List<Line>();
            if (payload.containsKey('lines') && payload.get('lines') != null) {
                Object linesObj = payload.get('lines');
                if (linesObj instanceof List) {
                    List<Object> rawLines = (List<Object>) linesObj;
                    for (Object rawLine : rawLines) {
                        if (!(rawLine instanceof Map)) {
                            throw new PayloadException('Each line must be a JSON object');
                        }
                        Map<String, Object> lineMap = (Map<String, Object>) rawLine;

                        // sku (required)
                        if (!lineMap.containsKey('sku') || lineMap.get('sku') == null) {
                            throw new PayloadException('Line is missing sku');
                        }
                        Object skuObj = lineMap.get('sku');
                        if (!(skuObj instanceof String)) {
                            throw new PayloadException('Line sku is not a string');
                        }
                        String sku = (String) skuObj;

                        // quantity (required, positive integer)
                        if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                            throw new PayloadException('Line is missing quantity');
                        }
                        Integer quantity = toInteger(lineMap.get('quantity'), 'quantity');
                        if (quantity <= 0) {
                            throw new PayloadException('Line quantity is non-positive');
                        }

                        // unitPrice (required, non-negative)
                        if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                            throw new PayloadException('Line is missing unitPrice');
                        }
                        Decimal unitPrice = toDecimal(lineMap.get('unitPrice'), 'unitPrice');
                        if (unitPrice < 0) {
                            throw new PayloadException('Line unitPrice is negative');
                        }

                        // discount (optional, default 0)
                        Decimal discount = 0;
                        if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                            discount = toDecimal(lineMap.get('discount'), 'discount');
                        }

                        // lineTotal = quantity * unitPrice * (1 - discount), rounded 2 dp half-up
                        Decimal rawTotal = quantity * unitPrice * (1 - discount);
                        Decimal lineTotal = roundHalfUp2(rawTotal);

                        Line line = new Line();
                        line.sku = sku;
                        line.quantity = quantity;
                        line.unitPrice = unitPrice;
                        line.discount = discount;
                        line.lineTotal = lineTotal;
                        order.lines.add(line);
                    }
                }
            }

            // total = sum of line totals
            order.total = 0;
            for (Line line : order.lines) {
                order.total += line.lineTotal;
            }

            return order;
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + String.valueOf(e.getMessage()));
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total == null ? (Decimal) 0 : order.total);
        return JSON.serialize(ack);
    }

    private static Decimal roundHalfUp2(Decimal value) {
        return Math.round(value * 100) / (Decimal) 100;
    }

    private static Integer toInteger(Object obj, String fieldName) {
        if (obj instanceof Integer) {
            return (Integer) obj;
        }
        if (obj instanceof Decimal) {
            Decimal d = (Decimal) obj;
            if (d.fractPart() != 0) {
                throw new PayloadException(fieldName + ' is not an integer');
            }
            return d.intValue();
        }
        throw new PayloadException(fieldName + ' is not a number');
    }

    private static Decimal toDecimal(Object obj, String fieldName) {
        if (obj instanceof Decimal) {
            return (Decimal) obj;
        }
        if (obj instanceof Integer) {
            return (Decimal) (Integer) obj;
        }
        throw new PayloadException(fieldName + ' is not a number');
    }
}
