public class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();
        result.successCount = 0;
        result.insertedIds = new List<Id>();
        result.errorsByIndex = new Map<Integer, String>();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Set<String> seenEmails = new Set<String>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            // Default LeadSource to Web when blank
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            // Enforce in-batch duplicate-email rule (case-insensitive, trimmed)
            if (!String.isBlank(lead.Email)) {
                String normalizedEmail = lead.Email.trim().toLowerCase();
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            leadsToInsert.add(lead);
            originalIndices.add(i);
        }

        // Single DML statement; does not throw on individual record failures
        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert);

            for (Integer i = 0; i < saveResults.size(); i++) {
                Database.SaveResult sr = saveResults[i];
                Integer originalIdx = originalIndices[i];

                if (sr.isSuccess()) {
                    result.insertedIds.add(sr.getId());
                    result.successCount++;
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIdx, String.join(messages, '; '));
                }
            }
        }

        return result;
    }
}
