public class OpportunityPipelineHandler {

    /**
     * Re-entrancy guard.
     * When we update Account, the existing AccountTrigger fires and updates
     * Opportunity (FB_Account_Rating__c), which re-fires this trigger.
     * The flag prevents an infinite loop.
     */
    private static Boolean isRecalculating = false;

    public static void handle() {
        if (isRecalculating) {
            return;
        }

        isRecalculating = true;
        try {
            // ------------------------------------------------------------------
            // 1. Determine every Account that may be affected
            // ------------------------------------------------------------------
            Set<Id> affectedAccountIds = new Set<Id>();

            if (Trigger.isInsert || Trigger.isUndelete) {
                for (Opportunity opp : Trigger.new) {
                    if (opp.AccountId != null) {
                        affectedAccountIds.add(opp.AccountId);
                    }
                }
            }

            if (Trigger.isUpdate) {
                for (Opportunity opp : Trigger.new) {
                    if (opp.AccountId != null) {
                        affectedAccountIds.add(opp.AccountId);
                    }
                }
                for (Opportunity opp : Trigger.old) {
                    if (opp.AccountId != null) {
                        affectedAccountIds.add(opp.AccountId);
                    }
                }
            }

            if (Trigger.isDelete) {
                for (Opportunity opp : Trigger.old) {
                    if (opp.AccountId != null) {
                        affectedAccountIds.add(opp.AccountId);
                    }
                }
            }

            if (affectedAccountIds.isEmpty()) {
                return;
            }

            // ------------------------------------------------------------------
            // 2. Current rollup values (so we can skip no-op DML)
            // ------------------------------------------------------------------
            Map<Id, Account> currentAccounts = new Map<Id, Account>(
                [SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
                 FROM Account
                 WHERE Id IN :affectedAccountIds]
            );

            // ------------------------------------------------------------------
            // 3. All open opportunities for those accounts (full recalc)
            //    In an after trigger the database already reflects the DML:
            //      - after insert/undelete : new rows are present
            //      - after update         : new values are committed
            //      - after delete         : rows are gone
            // ------------------------------------------------------------------
            List<Opportunity> openOpps = [
                SELECT AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :affectedAccountIds
                  AND IsClosed = false
            ];

            // ------------------------------------------------------------------
            // 4. Aggregate
            // ------------------------------------------------------------------
            Map<Id, Decimal> pipelineTotals = new Map<Id, Decimal>();
            Map<Id, Integer> oppCounts      = new Map<Id, Integer>();

            for (Opportunity opp : openOpps) {
                Decimal amount = (opp.Amount == null) ? 0 : opp.Amount;

                pipelineTotals.put(
                    opp.AccountId,
                    (pipelineTotals.containsKey(opp.AccountId) ? pipelineTotals.get(opp.AccountId) : 0) + amount
                );
                oppCounts.put(
                    opp.AccountId,
                    (oppCounts.containsKey(opp.AccountId) ? oppCounts.get(opp.AccountId) : 0) + 1
                );
            }

            // ------------------------------------------------------------------
            // 5. Build the update list (only when values actually changed)
            // ------------------------------------------------------------------
            List<Account> accountsToUpdate = new List<Account>();

            for (Id accId : affectedAccountIds) {
                if (!currentAccounts.containsKey(accId)) {
                    continue;   // account already gone in this transaction
                }

                Account acc = currentAccounts.get(accId);

                Decimal newPipeline = pipelineTotals.containsKey(accId) ? pipelineTotals.get(accId) : 0;
                Integer newCount    = oppCounts.containsKey(accId)    ? oppCounts.get(accId)    : 0;

                Decimal oldPipeline = (acc.FB_Open_Pipeline__c == null)    ? 0 : acc.FB_Open_Pipeline__c;
                Integer oldCount    = (acc.FB_Open_Opportunities__c == null) ? 0 : acc.FB_Open_Opportunities__c;

                if (oldPipeline != newPipeline || oldCount != newCount) {
                    acc.FB_Open_Pipeline__c    = newPipeline;
                    acc.FB_Open_Opportunities__c = newCount;
                    accountsToUpdate.add(acc);
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }

        } finally {
            isRecalculating = false;
        }
    }
}
