public class OpportunityRollupService {

    /**
     * Returns the closed-won opportunity revenue for the current calendar year,
     * keyed by Account Id. Every requested Id is present (defaulting to 0 when
     * there is no qualifying revenue). Respects the running user's sharing rules.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Current calendar-year boundaries (half-open interval)
        Integer year = DateTime.now().year();
        Date yearStart = Date.newInstance(year, 1, 1);
        Date yearEnd   = Date.newInstance(year + 1, 1, 1);

        // Single aggregate query – no individual Opportunity rows are loaded.
        // WITH SECURITY_ENFORCED guarantees record-level sharing is applied.
        List<AggregateResult> results = [
            WITH SECURITY_ENFORCED
            SELECT AccountId, SUM(Amount) TotalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate >= :yearStart
              AND CloseDate <  :yearEnd
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Seed every requested account with 0 so the map is complete.
        Map<Id, Decimal> resultMap = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            resultMap.put(accountId, 0);
        }

        // Overwrite with the actual sum; SUM of all-null Amounts returns null → 0.
        for (AggregateResult ar : results) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('TotalAmount');
            resultMap.put(accountId, total == null ? 0 : total);
        }

        return resultMap;
    }
}
