        Set<Id> accountIds = new Set<Id>{ idGen.newId(Account.SObjectType) };

        List<Opportunity> opps = new List<Opportunity>{
            new Opportunity(
                Id = idGen.newId(Opportunity.SObjectType),
                AccountId = accountIds[0],
                StageName = 'Prospecting',
                Amount = 10000,
                Probability = 10
            ),
            new Opportunity(
                Id = idGen.newId(Opportunity.SObjectType),
                AccountId = accountIds[0],
                StageName = 'Prospecting',
                Amount = 5000,
                Probability = 20
            ),
            new Opportunity(
                Id = idGen.newId(Opportunity.SObjectType),
                AccountId = accountIds[0],
                StageName = 'Negotiation',
                Amount = 33.33,
                Probability = 7
            )
        };
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opps);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

