public without sharing class Application {

    public static fflib_Application.UnitOfWorkFactory UnitOfWork;
    public static fflib_Application.ServiceFactory Service;
    public static fflib_Application.SelectorFactory Selector;
    public static fflib_Application.DomainFactory Domain;

    static {
        // ── Unit of Work ──────────────────────────────────────────────
        // One UoW that can register/commit Accounts, Contacts,
        // Opportunities and OpportunityContactRoles together,
        // resolving cross-entity Id references on insert.
        UnitOfWork = new fflib_Application.UnitOfWorkFactory();
        UnitOfWork.addSObject(Account.SObjectType);
        UnitOfWork.addSObject(Contact.SObjectType);
        UnitOfWork.addSObject(Opportunity.SObjectType);
        UnitOfWork.addSObject(OpportunityContactRole.SObjectType);

        // ── Services ──────────────────────────────────────────────────
        // IAccountsService  →  AccountsServiceImpl
        Service = new fflib_Application.ServiceFactory();
        Service.addService(IAccountsService.class, AccountsServiceImpl.class);

        // ── Selectors ─────────────────────────────────────────────────
        // Account  →  AccountsSelector
        // Contact  →  ContactsSelector
        Selector = new fflib_Application.SelectorFactory();
        Selector.addSelector(Account.SObjectType, new AccountsSelector());
        Selector.addSelector(Contact.SObjectType, new ContactsSelector());

        // ── Domains ───────────────────────────────────────────────────
        // Account  →  Accounts (uses the Selector factory above for
        //             querying in newInstance(Set<Id>) so that
        //             Application.Domain.newInstance(ids) resolves
        //             records through AccountsSelector).
        Domain = new fflib_Application.DomainFactory();
        Domain.addDomain(Account.SObjectType, new Accounts.Constructor(), Selector);
    }
}
