public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {}

        public Opportunities construct() {
            return new Opportunities(this);
        }
    }

    public Opportunities(fflib_SObjectDomain.IConstructable constructor) {
        super(
            new fflib_SObjectDomain(
                Opportunity.SObjectType,
                constructor,
                new List<fflib_SObjectTriggerHandlerBase__ndc__>{
                    new FulfilmentHandler()
                }
            )
        );
    }

    private class FulfilmentHandler extends fflib_SObjectTriggerHandlerBase__ndc__ {

        public void afterInsert() {
            Set<Id> qualifyingIds = new Set<Id>();
            for (Opportunity opp : (List<Opportunity>) this.records) {
                if (opp.StageName == 'Closed Won') {
                    qualifyingIds.add(opp.Id);
                }
            }
            if (!qualifyingIds.isEmpty()) {
                Application.Service.newInstance(IOpportunityFulfilmentService.class)
                    .startFulfilment(qualifyingIds);
            }
        }

        public void afterUpdate() {
            Set<Id> qualifyingIds = new Set<Id>();
            Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) this.oldRecords;
            for (Opportunity opp : (List<Opportunity>) this.records) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                    qualifyingIds.add(opp.Id);
                }
            }
            if (!qualifyingIds.isEmpty()) {
                Application.Service.newInstance(IOpportunityFulfilmentService.class)
                    .startFulfilment(qualifyingIds);
            }
        }
    }
}
