public class Accounts extends fflib_SObjects implements IAccounts {

    public static IAccounts newInstance(List<Account> records) {
        List<Schema.SObject> sObjectList = new List<Schema.SObject>();
        for (Account acc : records) {
            sObjectList.add(acc);
        }
        return (IAccounts) Application.Domain.newDomain(Account.SObjectType, sObjectList);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newDomain(Account.SObjectType, accountIds);
    }

    public class Constructor extends Accounts {
        public Constructor(List<Schema.SObject> records) {
            super(records);
        }
    }

    public Accounts(List<Schema.SObject> records) {
        super(records);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public Schema.SObjectType getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        List<Account> accounts = new List<Account>();
        for (Schema.SObject obj : getSObjectList()) {
            accounts.add((Account) obj);
        }
        return accounts;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (Account acc : getAccounts()) {
            if (acc.Rating == rating) {
                filtered.add(acc);
            }
        }
        return newInstance(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : getAccounts()) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account acc : getAccounts()) {
            acc.Rating = rating;
        }
    }
}
