public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {
        }
        public fflib_SObjectDomain create(SObject sobj) {
            return new Opportunities(sobj);
        }
    }

    private static final Map<String, fflib_SObjectDomain.ValidationRule> validationRules =
        new Map<String, fflib_SObjectDomain.ValidationRule>{
            'AmountCannotBeNegative' => new fflib_SObjectDomain.ValidationRule('AmountCannotBeNegative', 'AmountCannotBeNegative'),
            'AmountCannotChangeOnWon' => new fflib_SObjectDomain.ValidationRule('AmountCannotChangeOnWon', 'AmountCannotChangeOnWon')
        };

    public Opportunities(SObject sobj) {
        super(sobj, validationRules);
    }

    private void AmountCannotBeNegative() {
        if (Trigger.isInsert || Trigger.isUpdate) {
            Opportunity opp = (Opportunity) sobj;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    private void AmountCannotChangeOnWon() {
        if (Trigger.isUpdate) {
            Opportunity newOpp = (Opportunity) sobj;
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(newOpp.Id);
            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && newOpp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', newOpp, 'Amount');
            }
        }
    }
}
