            Account.Industry
        };
        fields.addAll(getCreditReviewFieldSetFields());
        return fields;
    }

    public virtual fflib_DataAccess getDataAccess() {
        fflib_DataAccess dataAccess = new fflib_DataAccess();
        dataAccess.accessLevel = fflib_DataAccess.AccessLevel.USER_MODE;
        return dataAccess;
    }

    /**
     * Fields belonging to the Credit_Review field set on Account.
     * Keep in sync when the field set is updated by admins.
     */
    private List<Schema.SObjectField> getCreditReviewFieldSetFields() {
        return new List<Schema.SObjectField>{
            Account.AnnualRevenue,
            Account.Rating
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_DataAccess dataAccess = getDataAccess();

        List<String> accountFieldNames = getFieldApiNames(getSObjectFieldList());

        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contactFieldNames = getFieldApiNames(contactsSelector.getSObjectFieldList());

        String withClause = (dataAccess.accessLevel == fflib_DataAccess.AccessLevel.USER_MODE)
            ? 'WITH USER_MODE '
            : '';

        String soql = withClause
            + 'SELECT ' + String.join(accountFieldNames, ', ')
            + ', (SELECT ' + String.join(contactFieldNames, ', ')
            + ' FROM Contacts) FROM Account WHERE Id IN :accountIds';

        return (List<Account>) Database.query(soql);
    }

    private List<String> getFieldApiNames(List<Schema.SObjectField> fields) {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : fields) {
            names.add(field.getDescribe().getName());
        }
        return names;
    }
