public class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Skip opportunities already at Closed Won
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // Build platform events for every opportunity we are closing
        List<Deal_Won__e> events = new List<Deal_Won__e>(toClose.size());
        for (Opportunity opp : toClose) {
            events.add(new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(opp.Id),
                Amount__c = opp.Amount
            ));
        }

        // Use a single unit of work: queue the DML, register the event
        // publishing as a post-commit callback, then commit once.
        // If commit() fails the runOnCommit callback is never invoked,
        // no events are published, and the exception propagates to the caller.
        fflib_IUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.updateSObjects(toClose);
        uow.runOnCommit(new PublishDealWonEvents(events));
        uow.commit();

        return toClose.size();
    }

    private class PublishDealWonEvents implements Runnable {
        private List<Deal_Won__e> events;

        public PublishDealWonEvents(List<Deal_Won__e> events) {
            this.events = events;
        }

        public void run() {
            if (!events.isEmpty()) {
                Database.insert(events);
            }
        }
    }
}
